const we4Table = table(['Step', 'Working'], [['Multiply top and bottom by $1 - \\cos\\theta$', '$\\dfrac{\\sin\\theta(1 - \\cos\\theta)}{(1 + \\cos\\theta)(1 - \\cos\\theta)}$'], ['Denominator', '$= \\dfrac{\\sin\\theta(1 - \\cos\\theta)}{1 - \\cos^2\\theta} = \\dfrac{\\sin\\theta(1 - \\cos\\theta)}{\\sin^2\\theta}$'], ['Cancel $\\sin\\theta$', '$= \\dfrac{1 - \\cos\\theta}{\\sin\\theta}$'], ['Check at $60^\\circ$', '$\\dfrac{\\frac{\\sqrt{3}}{2}}{\\frac{3}{2}} = \\dfrac{\\sqrt{3}}{3} = \\dfrac{\\frac{1}{2}}{\\frac{\\sqrt{3}}{2}}$']], 'Working table proving sine over one plus cosine equals one minus cosine over sine: multiply top and bottom by one minus cosine; the denominator becomes sine squared; cancel one sine. At sixty degrees both sides equal root three over three.', 'Multiplying by the conjugate $1 - \\cos\\theta$ gives $\\sin^2\\theta$.');
const givenFlow = flow('LR', [['g', 'One ratio is given'], ['i', 'Identity gives the other ratio'], ['a', 'All six ratios as fractions'], ['s', 'Substitute and simplify']], [['g', 'i'], ['i', 'a'], ['a', 's']], 'Flow chart for evaluating an expression when one ratio is given: use an identity to find the other ratios, write all six as exact fractions, then substitute and simplify.', 'Four steps for evaluating with a given ratio.');
// WE5: sin = 12/37 -> sec + tan = 7/5
const f5 = fromSin(12, 37);
must(tx(G('cos(T)', f5)) === '\\dfrac{35}{37}' && tx(G('sec(T)', f5)) === '\\dfrac{37}{35}' && tx(G('tan(T)', f5)) === '\\dfrac{12}{35}' && tx(G('sec(T)+tan(T)', f5)) === '\\dfrac{7}{5}' && 37 * 37 - 12 * 12 === 1225 && 35 * 35 === 1225 && 37 + 12 === 49 && 49 / 35 === 1.4, 'we5');
const we5Table = table(['Step', 'Working'], [['Find $\\cos\\theta$', '$\\cos^2\\theta = 1 - \\dfrac{144}{1369} = \\dfrac{1225}{1369}$, so $\\cos\\theta = \\dfrac{35}{37}$'], ['Find $\\sec\\theta$ and $\\tan\\theta$', '$\\sec\\theta = \\dfrac{37}{35}$, $\\tan\\theta = \\dfrac{12}{37} \\div \\dfrac{35}{37} = \\dfrac{12}{35}$'], ['Add', '$\\sec\\theta + \\tan\\theta = \\dfrac{37 + 12}{35} = \\dfrac{49}{35} = \\dfrac{7}{5}$']], 'Working table for sine theta equals twelve over thirty-seven: cosine squared is one thousand two hundred twenty-five over one thousand three hundred sixty-nine, so cosine is thirty-five over thirty-seven; secant is thirty-seven over thirty-five and tangent is twelve over thirty-five; their sum is forty-nine over thirty-five, which is seven over five.', 'Exact fractions all the way: no decimals.');
// WE6: (1 + tan^2)(1 - sin)(1 + sin) = 1
chain('(1+tan(A)^2)*(1-sin(A))*(1+sin(A))', 'sec(A)^2*(1-sin(A)^2)', 'sec(A)^2*cos(A)^2', '1');
must(X('(1+tan(A)^2)*(1-sin(A))*(1+sin(A))', { A: 60 }) === '1' && X('1+tan(A)^2', { A: 60 }) === '4' && X('(1-sin(A))*(1+sin(A))', { A: 60 }) === '\\dfrac{1}{4}', 'we6 numeric at 60');
const we6Table = table(['Step', 'Working'], [['Use two identities', '$(1 + \\tan^2\\theta) = \\sec^2\\theta$ and $(1 - \\sin\\theta)(1 + \\sin\\theta) = 1 - \\sin^2\\theta = \\cos^2\\theta$'], ['Multiply', '$\\sec^2\\theta \\times \\cos^2\\theta = \\dfrac{1}{\\cos^2\\theta} \\times \\cos^2\\theta$'], ['Result', '$= 1$'], ['Check at $60^\\circ$', '$(1 + 3) \\times \\dfrac{1}{4} = 1$']], 'Working table simplifying one plus tangent squared times one minus sine times one plus sine: the first factor is secant squared, the other two give cosine squared, and the product is one. At sixty degrees the value is four times one quarter, which is one.', 'A product of three factors collapses to the number $1$.');
const trapTable = table(['Common slip', 'Why it is wrong', 'Correct step'], [['$\\sin\\theta + \\cos\\theta = 1$', 'only the squares add to $1$; at $45^\\circ$ the sum is $\\sqrt{2}$', '$\\sin^2\\theta + \\cos^2\\theta = 1$'], ['$\\sqrt{1 - \\cos^2\\theta} = \\sin^2\\theta$', 'the square root gives a power one, not two', '$\\sqrt{1 - \\cos^2\\theta} = \\sin\\theta$'], ['$\\sin^2\\theta + \\sin^2(90^\\circ - \\theta) = 0$', 'complement turns sine into cosine', '$= \\sin^2\\theta + \\cos^2\\theta = 1$'], ['Moving a term across the equals sign in a proof', 'a proof must not assume the result', 'simplify one side until it equals the other']], 'Table of common slips: sine plus cosine is not one, only the squares add to one; the square root of one minus cosine squared is sine, not sine squared; sine squared of an angle plus sine squared of its complement is one, not zero; and a proof must work on one side only.', 'Four slips to avoid.');
must(X('sin(A)+cos(A)', { A: 45 }) === '\\sqrt{2}' && identity('sin(A)^2+sin(90-A)^2', '1') > 0, 'trap table');
const sum2 = table(['Idea', 'Key fact'], [['Complementary angles', '$\\sin(90^\\circ - \\theta) = \\cos\\theta$, $\\tan(90^\\circ - \\theta) = \\cot\\theta$, $\\sec(90^\\circ - \\theta) = \\operatorname{cosec}\\theta$'], ['Proving', 'work on one side; use sine and cosine; combine fractions; conjugates'], ['Conjugates', '$(1 - \\sin\\theta)(1 + \\sin\\theta) = \\cos^2\\theta$ and similar'], ['Evaluating', 'find the other ratios from the given one with an identity, then substitute'], ['Check', 'test at $30^\\circ$, $45^\\circ$ or $60^\\circ$ to catch slips']], 'Summary table for part two: complementary-angle rules, strategy for proving identities, conjugate pairs, evaluating with a given ratio, and checking with a standard angle.', 'Part 2 on one card.');

